import{_ as a,c as t,o as n,ag as s}from"./chunks/framework.BlG8Ex8O.js";const i="/assets/js-quiz-app.CnWLTDNU.jpg",g=JSON.parse('{"title":"From Mindless Scrolling to Something Useful - AI quiz for practicing Java Script","description":"How I created a quiz app with AI for practicing JS skills.","frontmatter":{"title":"From Mindless Scrolling to Something Useful - AI quiz for practicing Java Script","date":"2025-12-19T00:00:00.000Z","description":"How I created a quiz app with AI for practicing JS skills.","image":"","tags":["AI","Java Script"]},"headers":[],"relativePath":"posts/js-quizz-ai.md","filePath":"posts/js-quizz-ai.md"}'),r={name:"posts/js-quizz-ai.md"};function o(l,e,p,h,d,c){return n(),t("div",null,[...e[0]||(e[0]=[s(`<h2 id="from-mindless-scrolling-to-something-useful" tabindex="-1">From Mindless Scrolling to Something Useful <a class="header-anchor" href="#from-mindless-scrolling-to-something-useful" aria-label="Permalink to &quot;From Mindless Scrolling to Something Useful&quot;">​</a></h2><p>Usually, before going to bed - or already in bed - I’d catch myself scrolling through reels, jumping between different social media apps without any real purpose. Just wasting precious time that should’ve gone to sleep.</p><p>Then one night I thought: if I’m not sleeping anyway, why waste time pointlessly? Why not learn something or read something useful?</p><p>Even though my phone is a Pro Max with a big screen, I never really managed to use it like a Kindle or a tablet for reading books. It just didn’t work for me.</p><h2 id="the-interview-questions-idea" tabindex="-1">The Interview Questions Idea <a class="header-anchor" href="#the-interview-questions-idea" aria-label="Permalink to &quot;The Interview Questions Idea&quot;">​</a></h2><p>Around that time, I had been reading interview questions, mostly JavaScript-related. I started going through them on GitHub, but honestly, it wasn’t a great experience. Every time I opened the page, I’d start from the top again, read the first 10 or 15 questions, and then stop-out of more than 150.</p><p>That’s when another thought hit me:</p><p><strong>What if I had a quiz that I could access from anywhere?</strong></p><p>The questions already existed in a <a href="https://github.com/lydiahallie/javascript-questions" target="_blank" rel="noreferrer">public GitHub repository</a> by Lydia Hallie. All I needed was to fetch the questions from the Markdown file, iterate through them, and deploy the app somewhere. I could’ve done something similar with ChatGPT or Claude, but I specifically wanted a quiz experience.</p><h2 id="building-it-without-overthinking" tabindex="-1">Building It (Without Overthinking) <a class="header-anchor" href="#building-it-without-overthinking" aria-label="Permalink to &quot;Building It (Without Overthinking)&quot;">​</a></h2><p>I didn’t want to spend too much time on this. It’s a simple project - almost a junior-level one - and I already knew what needed to be done. So I decided to try one of the free AI tools to scaffold the app quickly and then polish it later.</p><p>This was the main prompt I used.</p><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki github-dark vp-code" tabindex="0"><code><span class="line"><span>I want you to create a quiz web app using the questions and answers from the following Markdown (.md) file.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Steps:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- First, extract the questions and answers from the file (you may use a script for this).</span></span>
<span class="line"><span>This should be straightforward since the file is written in Markdown and the questions are numbered.</span></span>
<span class="line"><span>The answers are located below each question in an accordion-style section.</span></span>
<span class="line"><span>- Use the extracted data to build the flashcards interface.</span></span>
<span class="line"><span>- Upload the finished project to GitHub and deploy it on Vercel.</span></span>
<span class="line"><span>Here is the file you should use:</span></span>
<span class="line"><span>https://github.com/lydiahallie/javascript-questions/blob/master/README.md</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Please read the file first and ask me for clarification before proceeding if anything is unclear.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>P.S. To avoid fetching the file at runtime, you may copy the Markdown file directly into the project and read the data from there.</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br></div></div><p>Without any specific reason, I chose <a href="https://lovable.dev" target="_blank" rel="noreferrer">lovable.dev</a>, and surprisingly, it did a pretty good job.</p><p>After that, I connected it to my GitHub account and deployed it on Vercel.</p><h2 id="the-result" tabindex="-1">The Result <a class="header-anchor" href="#the-result" aria-label="Permalink to &quot;The Result&quot;">​</a></h2><p>And that was it. I ended up with a JavaScript quiz app containing <strong>155 questions</strong>, all parsed from Lydia Hallie’s repository. The app includes:</p><ul><li><strong>Dark theme</strong> with JavaScript-inspired yellow accents</li><li><strong>Code syntax highlighting</strong> using the JetBrains Mono font</li><li><strong>Progress tracking</strong> with score and accuracy</li><li><strong>Shuffle &amp; Reset</strong> functionality</li><li><strong>Keyboard navigation</strong> (arrow keys)</li><li><strong>Completion screen</strong> with shareable results</li></ul><p><img src="`+i+'" alt="JavaScript quiz app dark mode UI"></p><p>You can check it on the following link: <a href="https://jsquizz-ngp.vercel.app/" target="_blank" rel="noreferrer">https://jsquizz-ngp.vercel.app/</a>.</p><h2 id="a-better-alternative-to-scrolling" tabindex="-1">A Better Alternative to Scrolling <a class="header-anchor" href="#a-better-alternative-to-scrolling" aria-label="Permalink to &quot;A Better Alternative to Scrolling&quot;">​</a></h2><p>And I actually did it. Instead of endlessly scrolling through Instagram or Facebook feeds full of mostly useless content, I now had a much better alternative - something that actually helps me learn.</p><h2 id="what-s-next" tabindex="-1">What’s Next? <a class="header-anchor" href="#what-s-next" aria-label="Permalink to &quot;What’s Next?&quot;">​</a></h2><p>I could easily connect this to a database like Supabase and add user profiles with progress tracking. I’m also thinking about adding different types of questions: Python, React, Next.js, Vue, and more.</p><p>But that might be a topic for another blog post.</p>',25)])])}const m=a(r,[["render",o]]);export{g as __pageData,m as default};
